<?php include "auth.php";include "conection.php";if($_SERVER['REQUEST_METHOD']!=='POST'){header("Location:tampil.php");exit;}$id=(int)($_POST['id_aspirasi']??0);$sid=(int)($_POST['id_siswa']??0);$kat=trim($_POST['kategori']??'');$isi=trim($_POST['isi_aspirasi']??'');if($id<1||$sid<1||$kat===''||$isi==='')die("Data belum lengkap.");$cek=$conn->prepare("SELECT id_siswa FROM siswa WHERE id_siswa=?");$cek->bind_param("i",$sid);$cek->execute();if($cek->get_result()->num_rows===0)die("Siswa tidak ditemukan.");$s=$conn->prepare("UPDATE id_aspirasi SET id_siswa=?,kategori=?,isi_aspirasi=? WHERE id_aspirasi=?");$s->bind_param("issi",$sid,$kat,$isi,$id);if($s->execute()){header("Location:index.php?status=edit");exit;}die("Gagal mengubah data: ".htmlspecialchars($s->error));